class Solution {
public:
    int reductionOperations(vector<int>& nums) {
        int n = nums.size();
        int maxVal = 0;
        for (int x : nums) maxVal = max(maxVal, x);

        vector<int> freq(maxVal + 1, 0);
        for (int x : nums) freq[x]++;

        long long suffix = 0;
        long long answer = 0;
        for (int v = maxVal; v >= 1; v--) {
            suffix += freq[v];
            if (freq[v] > 0 && suffix < n) {
                answer += suffix;
            }
        }
        return (int)answer;
    }
};
